type mailListJoins[Q dialect.Joinable] struct {
	typ                      string
	CreatedByUserUserProfile modAs[Q, userProfileColumns]
	UpdatedByUserUserProfile modAs[Q, userProfileColumns]
	ListMailListRecipients   modAs[Q, mailListRecipientColumns]
	ListMailings             modAs[Q, mailingColumns]
}

func (j mailListJoins[Q]) aliasedAs(alias string) mailListJoins[Q] {
	return buildMailListJoins[Q](buildMailListColumns(alias), j.typ)
}

func buildMailListJoins[Q dialect.Joinable](cols mailListColumns, typ string) mailListJoins[Q] {
	return mailListJoins[Q]{
		typ: typ,
		CreatedByUserUserProfile: modAs[Q, userProfileColumns]{
			c: UserProfiles.Columns,
			f: func(to userProfileColumns) bob.Mod[Q] {
				mods := make(mods.QueryMods[Q], 0, 1)

				{
					mods = append(mods, dialect.Join[Q](typ, UserProfiles.Name().As(to.Alias())).On(
						to.ID.EQ(cols.CreatedByUserID),
					))
				}

				return mods
			},
		},
		UpdatedByUserUserProfile: modAs[Q, userProfileColumns]{
			c: UserProfiles.Columns,
			f: func(to userProfileColumns) bob.Mod[Q] {
				mods := make(mods.QueryMods[Q], 0, 1)

				{
					mods = append(mods, dialect.Join[Q](typ, UserProfiles.Name().As(to.Alias())).On(
						to.ID.EQ(cols.UpdatedByUserID),
					))
				}

				return mods
			},
		},
		ListMailListRecipients: modAs[Q, mailListRecipientColumns]{
			c: MailListRecipients.Columns,
			f: func(to mailListRecipientColumns) bob.Mod[Q] {
				mods := make(mods.QueryMods[Q], 0, 1)

				{
					mods = append(mods, dialect.Join[Q](typ, MailListRecipients.Name().As(to.Alias())).On(
						to.ListID.EQ(cols.ID),
					))
				}

				return mods
			},
		},
		ListMailings: modAs[Q, mailingColumns]{
			c: Mailings.Columns,
			f: func(to mailingColumns) bob.Mod[Q] {
				mods := make(mods.QueryMods[Q], 0, 1)

				{
					mods = append(mods, dialect.Join[Q](typ, Mailings.Name().As(to.Alias())).On(
						to.ListID.EQ(cols.ID),
					))
				}

				return mods
			},
		},
	}
}
